  'stuSess.refundSuccessStripeNote': '<p class="text-emerald-900 text-sm mb-2">Jautājumi vai problēmas? Sazinieties ar <a href="mailto:info@tutlio.lt" class="underline font-medium">info@tutlio.lt</a>.</p><p class="font-semibold text-emerald-900">Jūsu atmaksa ir uzsākta caur Stripe.</p><p class="text-emerald-800 mt-1">Kartes atmaksas parasti pienāk aptuveni <strong>5–10 darba dienu laikā</strong> (bankas var atšķirties). Ja nesaņemat to parastajā termiņā, rakstiet uz <a href="mailto:info@tutlio.lt" class="text-emerald-900 underline font-medium">info@tutlio.lt</a>.</p>',
  'stuSess.refundSuccessManualTutor': '<p>Šī nodarbība neizskatās, ka tā būtu apmaksāta caur Tutlio Stripe (piem. bankas pārskaitījums vai skaidra nauda). Automātiskas atmaksas šeit nav.</p><p class="mt-2">Lai vienotos par atmaksu, sazinieties ar savu pasniedzēju <strong>{tutor}</strong> — izmantojiet e-pastu vai detaļas no savām rezervācijām vai tieši no pasniedzēja.</p>',
  'stuSess.refundSuccessManualOrg': '<p>Šī nodarbība neizskatās, ka tā būtu apmaksāta caur Tutlio Stripe (piem. bankas pārskaitījums vai skaidra nauda). Automātiskas atmaksas šeit nav.</p><p class="mt-2">Tā kā mācāties caur organizāciju, sazinieties ar <strong>organizācijas administratoru</strong> (caur savu pasniedzēju vai organizācijas publicētajiem kontaktiem).</p>',
  'stuSess.refundTutorFallback': 'jūsu pasniedzēju',

