  // --- priv (Privātuma politika) ---

  // --- tos (Lietošanas noteikumi) ---

  'orgTutorPolicy.title': 'Iekšējie noteikumi pasniedzējiem',
  'orgTutorPolicy.intro': 'Pirms platformas izmantošanas, lūdzu, iepazīstieties ar organizācijas iekšējiem noteikumiem.',
  'orgTutorPolicy.acceptBtn': 'Sapratu',
  'orgTutorPolicy.viewBtn': 'Skatīt iekšējos noteikumus',
  'orgTutorPolicy.s1Title': '1. Vispārīgie noteikumi',
  'orgTutorPolicy.s1Body': 'Šie noteikumi reglamentē Tutlio platformas („Platforma“) lietošanu skolotāja vai pasniedzēja („Pasniedzējs“) statusā. Jūs izmantot Platformu ir uzaicinājusi izglītības aģentūra, skola vai mācību centrs, kuru pārstāvat („Organizācija“). Platformu tehniski uztur un apkalpo MB Tutlio. Izmantojot savu kontu, jūs piekrītat šiem noteikumiem un Privātuma politikai.',
  'orgTutorPolicy.s2Title': '2. Konta pārvaldība un grafiki',
  'orgTutorPolicy.s2Intro': 'Platforma ir izstrādāta tā, lai jums nebūtu jātērē laiks nodarbību laiku saskaņošanai ar skolēniem.',
  'orgTutorPolicy.s2Link': 'Unikālā saite: Jums tiek piešķirta personīga nodarbību rezervēšanas saite (pēc pasniegšanas priekšmetiem), ko skolēni izmanto nodarbību pieteikšanai.',
  'orgTutorPolicy.s2Calendar': 'Kalendāra sinhronizācija: Jūsu pieejamība ir tieši atkarīga no Google Calendar integrācijas (divvirzienu sinhronizācija). Jūs esat personiski atbildīgs par to, lai jūsu kalendārā norādītais brīvais laiks būtu aktuāls un pareizs. Platforma neļaus skolēniem rezervēt laiku, kas jūsu kalendārā atzīmēts kā aizņemts.',
  'orgTutorPolicy.s2Security': 'Konta drošība: Jūsu konts ir personisks. Jums ir jāglabā pieteikšanās dati drošībā un nav jānodod tos trešajām personām.',
  'orgTutorPolicy.s3Title': '3. Nodarbību atcelšana un gaidīšanas saraksts',
  'orgTutorPolicy.s3Intro': 'Platforma palīdz maksimāli aizpildīt jūsu grafiku un izvairīties no tukšiem logiem:',
  'orgTutorPolicy.s3Auto': 'Ja skolēns atceļ nodarbību, Platforma automātiski nosūta paziņojumu (SMS/e-pastu) citiem skolēniem jūsu gaidīšanas sarakstā, piedāvājot atbrīvoto laiku. No jūsu puses nekādas papildu darbības nav nepieciešamas.',
  'orgTutorPolicy.s3Rules': 'Nodarbību atcelšanas noteikumus (cik ilgi iepriekš var atcelt, kādas sekas) nosaka jūsu Organizācija.',
  'orgTutorPolicy.s4Title': '4. Finanšu jautājumi un norēķini',
  'orgTutorPolicy.s4Intro': 'Jums nav jāuztraucas par rēķinu izrakstīšanu vai maksājumu iekasēšanu no vecākiem:',
  'orgTutorPolicy.s4Advance': 'Visi skolēnu (vai vecāku) maksājumi par jūsu nodarbībām tiek iekasēti avansā caur Platformu un pārskaitīti tieši jūsu Organizācijai.',
  'orgTutorPolicy.s4Confirmed': 'Jūs vadāt nodarbību tikai tad, kad tā ir apstiprināta sistēmā (tas nozīmē, ka maksa jau ir ieturēta).',
  'orgTutorPolicy.s4Contact': 'Par algu, izmaksu grafiku un citiem finanšu jautājumiem sazinieties tieši ar savas Organizācijas administratoru. MB Tutlio neveic nekādus tiešus finanšu norēķinus ar Pasniedzējiem.',
  'orgTutorPolicy.s5Title': '5. Skolēnu datu aizsardzība (VDAR)',
  'orgTutorPolicy.s5Intro': 'Kā Pasniedzējs jūs saņemat pieeju skolēnu personas datiem, iekšējām piezīmēm un mācību materiāliem. Jūs apņematies:',
  'orgTutorPolicy.s5Use': 'Izmantot šos datus tikai un vienīgi nodarbību organizēšanai un vadīšanai.',
  'orgTutorPolicy.s5NoCopy': 'Nekopēt, neeksportēt un neizplatīt skolēnu vai vecāku kontaktinformāciju ārpus Platformas.',
  'orgTutorPolicy.s5Notes': 'Aizsargāt Organizācijas iekšējos ierakstus (piezīmes par skolēna progresu), kas ir redzami tikai jums un Organizācijas administrācijai, nevis skolēniem vai vecākiem.',
  'orgTutorPolicy.s5Termination': 'Pēc jūsu darba attiecību izbeigšanas ar Organizāciju jūsu pieeja šiem datiem tiks nekavējoties anulēta.',
  'orgTutorPolicy.s6Title': '6. Tehniskā darbība un atbildības ierobežojums',
  'orgTutorPolicy.s6Body': 'Platformas izmantošana nelikumīgiem mērķiem, ļaunprātīgu saišu izplatīšana nodarbību materiālos vai citāda sistēmas darbības traucēšana ir aizliegta. MB Tutlio nodrošina Platformas darbību un tehnisko apkopi, taču neuzņemas atbildību par traucējumiem, kas radušies jūsu interneta savienojuma, ierīču kļūmju vai nepareizi konfigurētu Google Calendar iestatījumu dēļ.',
  'orgTutorPolicy.s7Title': '7. Atbalsts un kontakti',
  'orgTutorPolicy.s7Org': 'Ja jums ir jautājumi par nodarbību grafikiem, algu, skolēnu piešķiršanu vai darba organizēšanu, sazinieties ar savas Organizācijas administratoru.',
  'orgTutorPolicy.s7Tech': 'Ja saskaraties ar Platformas tehniskām kļūdām (nedarbojas kalendāra sinhronizācija, nesaņemat paziņojumus), informējiet Organizācijas administratoru, kurš sazināsies ar Tutlio tehniskā atbalsta komandu.',

