  'feature.cancellation.pageTitle': 'Atcelšanas noteikumi un novēlotas atcelšanas maksas pasniedzējiem',
  'feature.cancellation.pageDesc': 'Iestatiet skaidrus atcelšanas termiņus un automātiskas novēlotas atcelšanas maksas. Kad skolēni atceļ, atbrīvotie laiki uzreiz nonāk jūsu gaidītāju sarakstā.',
  'feature.cancellation.detailsTitle': 'Kā darbojas atcelšanas noteikumi',
  'feature.cancellation.deadlines': 'Atcelšanas termiņi',
  'feature.cancellation.deadlinesDesc': 'Norādiet, cik laicīgi skolēniem jāatceļ (piem., 24 stundas pirms nodarbības), lai izvairītos no atcelšanas maksas.',
  'feature.cancellation.fees': 'Automātiskas novēlotas atcelšanas maksas',
  'feature.cancellation.feesDesc': 'Iestatiet procentuālu maksu (piem., 50 % no nodarbības cenas), kas tiek automātiski piemērota, kad skolēns atceļ pārāk vēlu.',
  'feature.cancellation.transparency': 'Skaidra saziņa ar skolēniem',
  'feature.cancellation.transparencyDesc': 'Skolēni redz jūsu atcelšanas politiku uzreiz, rezervējot. Nekādu pārsteigumu — tikai profesionāli, godīgi noteikumi.',
  'feature.cancellation.waitlistLink': 'Integrācija ar gaidītāju sarakstu',
  'feature.cancellation.waitlistLinkDesc': 'Atceltie laiki uzreiz tiek piedāvāti gaidītāju saraksta skolēniem, tāpēc jūsu grafiks paliek pilns un ieņēmumi ir aizsargāti.',
  'feature.cancellation.faq.howSetQ': 'Kā iestatīt atcelšanas noteikumus?',
  'feature.cancellation.faq.howSetA': 'Dodieties uz nodarbību iestatījumiem un norādiet atcelšanas termiņu (stundas pirms nodarbības) un novēlotas atcelšanas maksas procentu. Sistēma tos piemēro automātiski.',
  'feature.cancellation.faq.refundQ': 'Kas notiek ar atcelšanas maksu?',
  'feature.cancellation.faq.refundA': 'Novēlotas atcelšanas maksas tiek automātiski aprēķinātas un pievienotas skolēna bilancei. Visas maksas varat izsekot finanšu panelī.',
  'feature.cancellation.faq.studentSeeQ': 'Vai skolēni redz atcelšanas politiku?',
  'feature.cancellation.faq.studentSeeA': 'Jā, jūsu atcelšanas nosacījumi tiek parādīti skolēniem rezervēšanas laikā, lai viņi zinātu noteikumus pirms apstiprināšanas.',
  'feature.comments.pageTitle': 'Nodarbību piezīmes, komentāri un failu koplietošana pasniedzējiem',
  'feature.comments.pageDesc': 'Pievienojiet piezīmes, mājasdarbus un failus atsevišķām nodarbībām. Izveidojiet pilnu nodarbību vēsturi, kas jebkurā laikā pieejama skolēniem un vecākiem.',
  'feature.comments.detailsTitle': 'Kā darbojas nodarbību piezīmes',
  'feature.comments.lessonNotes': 'Piezīmes katrai nodarbībai',
  'feature.comments.lessonNotesDesc': 'Pievienojiet privātas vai koplietotas piezīmes jebkurai nodarbībai — sekojiet līdzi tam, kas apgūts, skolēna progresam un nākamajiem soļiem.',
  'feature.comments.fileSharing': 'Failu pielikumi',
  'feature.comments.fileSharingDesc': 'Augšupielādējiet darba lapas, mājasdarbu PDF vai mācību materiālus un pievienojiet tos tieši nodarbībai ērtai piekļuvei.',
  'feature.comments.history': 'Pilna nodarbību vēsture',
  'feature.comments.historyDesc': 'Katra piezīme un fails ir saistīti ar attiecīgo nodarbību, veidojot meklējamu katra skolēna mācību ceļa laika līniju.',
  'feature.comments.parentAccess': 'Redzamība vecākiem',
  'feature.comments.parentAccessDesc': 'Vecāki savā portālā var redzēt koplietotās nodarbību piezīmes un failus, tādējādi esot informēti par sava bērna progresu.',
  'feature.comments.faq.whoSeesQ': 'Kas var redzēt nodarbību piezīmes?',
  'feature.comments.faq.whoSeesA': 'Jūs izvēlaties, ko koplietot. Piezīmes var būt privātas (tikai pasniedzējam) vai koplietotas ar skolēnu un viņa vecākiem.',
  'feature.comments.faq.fileTypesQ': 'Kādus failu tipus varu augšupielādēt?',
  'feature.comments.faq.fileTypesA': 'Varat augšupielādēt PDF, attēlus un izplatītus dokumentu formātus. Faili tiek glabāti droši un ir pieejami no jebkuras ierīces.',
  'feature.comments.faq.storageQ': 'Vai ir krātuves ierobežojums?',
  'feature.comments.faq.storageA': 'Visi plāni ietver dāsnu failu krātuvi. Nav ierobežojumu katram failam — pievienojiet tik daudz materiālu, cik nepieciešams.',
