  'schoolsLanding.faq.whoForA': 'Valodu skolām, mācību centriem, mūzikas skolām, eksāmenu sagatavošanas programmām un jebkurai organizācijai, kas pārvalda vairākus pasniedzējus un skolēnus.',
  'schoolsLanding.faq.contractsQ': 'Vai varam pārvaldīt līgumus un maksājumus?',
  'schoolsLanding.faq.contractsA': 'Jā. Platforma atbalsta līgumu veidnes, elektronisko parakstīšanu, maksājumu grafikus, Stripe maksājumus un finanšu atskaites.',
  'schoolsLanding.faq.pricingQ': 'Kā darbojas cenas skolām?',
  'schoolsLanding.faq.pricingA': 'Skolām tiek piemērotas individuālas cenas atkarībā no pasniedzēju skaita un vajadzībām. Sazinieties ar mums, lai saņemtu piedāvājumu.',
  'schoolsLanding.faq.trialQ': 'Vai var izmēģināt pirms pirkšanas?',
  'schoolsLanding.faq.trialA': 'Jā — piesakieties bezmaksas konsultācijai un demonstrācijai. Parādīsim, kā Tutlio iekļaujas jūsu skolas darbā.',

